-- agrees with its vehicle's mdc_main_body.

INSERT OR IGNORE INTO vehicles (slug, name, system, vehicle_class, crew, passengers, speed_ground, speed_air, speed_water, dimensions, weight_tons, mdc_main_body, is_mega_damage, ar, cost, cost_note, description, source_book) VALUES
  ('sovietski-cyborg-canine', 'Sovietski Cyborg Canine', 'rifts', 'borg', 'One trained, domesticated dog (Enhanced Cybernetic Animal, full conversion Light Machine); usually a large breed, sometimes a medium-sized one.', 'None.', 'Running: 90 mph (144 km) maximum, tiring at a third of the usual rate. Leaping: 10 feet (3 m) high or 25 feet (7.6 m) lengthwise; half again as far with a running start of 60 mph (96 km) or more.', 'None; cannot fly.', 'Swims on the surface at 24 mph (38.4 km); no underwater capability.', 'Average large breed: shoulder height 2 feet, 6 inches to 3 feet (0.8 to 0.9 m); width one foot, 6 inches (0.5 m); length 4-5 feet (1.2 to 1.5 m) from snout to rump, plus the tail. Varies with breed.', '300-400 pounds (135 to 180 kg).', 90, 1, NULL, 570000, 'Sovietski cost 570,000-650,000 credits for a full conversion Light Machine; 300,000 credits for a partial cyborg, which gets bionic legs and reinforcement only. Never sold on the Black Market. The low end of the full conversion range is stored.', 'A dog rebuilt as a Light Machine under the Sovietski''s Enhanced Animal Cyborg Program, serving the Army, the Police and Spetsnaz. The breeds used so far are big or mid-sized ones: the Caucasian Shepherd (fierce and risky even with the implant), the calm, mastiff-like Central Asian Shepherd, the Borzoi, the Black Russian Terrier long kept by police, and the Russo-European Laika, a boar and elk hunter. A partial conversion gets bionic legs and bracing; a full one is rebuilt from the frame up, with the head kept and only armored so the nose and ears lose nothing. Like every enhanced animal it carries a Neural Aggression Modulator Control (NAMC) implant for obedience, and its eyes and ears record and transmit everything to its assigned handler, a soldier (often a cyborg) it trains with and bonds to. It scouts, carries messages and small supply parcels, tracks, sniffs out bombs, guards and fights beside its squad; a low saddlebag pack lets it ferry kit such as lock picks or explosives into a prison break or a commando raid while its handler talks it through by radio. Robot P.S. 20 and Robot P.P. 20: 2D6 S.D.C. restrained bite, 1D6 M.D. full bite, 1D4 M.D. pounce or body block/ram; the pounce and ram each have an 80% chance to knock down anyone under 1,000 pounds (450 kg), who loses initiative and one attack and is -1 to parry and dodge while down. Four attacks per melee, NAMC bonus included. Bonuses (NAMC included): initiative +2, strike and pounce +3, dodge +4, disarm +3, pull bite +3. Natural abilities: Prowl 40%, Swimming 75%, tracking by scent 65% (hunting breeds +10%), picking out a particular smell (machine oil, explosives, Brodkil) 60%, +10% to identify and follow common or strong scents, leap and pounce attacks; it senses the supernatural and werebeasts within 200 feet (61 m), down from 600 feet (183 m) for a partial cyborg, and signals by barking twice and pointing. It is trained to break off and retreat once its head or main body falls to 20% of its M.D.C. Power: nuclear, 15 year life. Bionic features: Optic Nerve Video Implant with audio, a Cyber-Camera Eye with telescopic sight, passive nightvision, a thermal-imager, a built-in radio receiver and transmitter headjack, a Molecular Analyzer, a gas-filtering bionic lung with an oxygen storage cell, one internal storage compartment that only its handler or a known teammate can open (a pistol and E-Clip, a Vibro-Knife of 1D4 M.D., a pair of hand grenades, or a compact tool kit), and two Cyber-Nano-Robot Repair Systems.', 'Rifts World Book 36: Sovietski p.150-153'),
  ('sovietski-cyborg-bear', 'Sovietski Cyborg Bear', 'rifts', 'borg', 'One tamed and trained bear (Enhanced Cybernetic Animal, full conversion Heavy Machine); usually a Russian brown bear, Kodiak or polar bear.', 'None.', 'Running: 60 mph (96 km) maximum, tiring at a third of the usual rate. Leaping: 6 feet (1.8 m) high or 10 feet (3 m) lengthwise, plus 20% with a full speed running start; the legs are not built for leaping.', 'None; cannot fly.', 'Swims on the surface at 20 mph (32 km); no underwater capability.', 'Average full conversion: shoulder height 6 feet (1.8 m); width 3-4 feet (0.9 to 1.2 m); length 10-12 feet (3 to 3.7 m); 9 feet (2.7 m) tall reared on its hind legs. A partial conversion is the bear''s own size, up to 20% larger.', '2 tons.', 360, 1, NULL, 1400000, 'Sovietski cost 1.4 million credits for a full conversion Heavy Machine; 800,000 credits for a partial cyborg, which has a 190 M.D.C. main body and no built-in energy weapon or launchers, only M.D. jaws and claws. Never sold on the Black Market. The full conversion figure is stored.', 'A bear rebuilt as a Heavy Machine under the Sovietski''s Enhanced Animal Cyborg Program; the bear is a long-standing emblem of Russia. A bear''s nose is keener than a dog''s, but bears were never tame enough to put it to work until bionics and the Neural Aggression Modulator Control (NAMC) implant: an armored cyborg handler need not fear a mauling, and the implant gives the handler (most often a Light or Heavy Machine, though many are unaugmented) a close read on the animal and control of it. Too big for scouting or spying, it serves as monster hunter, attack animal, guard, tracker and rescuer, and is routinely sent to haul wounded soldiers and wrecked or paralyzed cyborgs, whose living occupant it can smell, back to the medics. Charging packs of them, up to three dozen at once, have been loosed as shock troops to break enemy lines; Spetsnaz like one along to intimidate, and one in the room loosens tongues at an interrogation. Its stat block calls it a Heavy Machine but heads its attributes Light Machine. Robot P.S. 40 and Robot P.P. 20: 1D4 M.D. restrained paw strike, 3D6+3 M.D. full claw strike, 2D6 M.D. bite, a pinning bear hug for 2D6 M.D. each melee round. A charging ram or a rearing pounce does 2D6 M.D., with a 95% chance to knock down anyone under 1,500 pounds (675 kg) and 60% against up to three tons; the fallen lose initiative and two attacks and are -2 to parry and dodge while down. Four attacks per melee, NAMC bonus included. Bonuses (NAMC included): initiative +1, strike +4, parry and dodge +2, disarm +3, pull punch or claw strike +1. Natural abilities: Climb 40% (too big to climb well), Prowl 35%, Swimming 68% (polar bears +20%), tracking by scent 80%, picking out a particular smell (machine oil, explosives, Brodkil) 75%, +10% to identify and follow common or strong scents; it senses the supernatural and werebeasts within 200 feet (61 m), down from 600 feet (183 m) for a partial cyborg, and is often set to hunt monsters and demons. Power: nuclear, 15 year life. Bionic features: Optic Nerve Video Implant with audio, a Cyber-Camera Eye with telescopic sight, passive nightvision, a thermal-imager, a built-in radio receiver and transmitter headjack, a Molecular Analyzer, a gas-filtering bionic lung with an oxygen storage cell, and three Cyber-Nano-Robot Repair Systems. Its handler steers it by radio just as with the cyborg dog.', 'Rifts World Book 36: Sovietski p.153-155');

INSERT OR IGNORE INTO vehicle_locations (vehicle_slug, location, mdc, mdc_note, ordinal) VALUES
  ('sovietski-cyborg-canine', 'Head', 80, 'Small target: Called Shot only, -3 to strike. Destroying the head kills the animal.', 1),
