INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('sovietski-cyborg-canine', 1, 'Bionic Jaws', '1D6 M.D. per full strength bite; 2D6 S.D.C./Hit Points on a restrained warning bite', 1, 'Melee.', NULL, NULL, NULL, 'Hunting, attack and defense. The head is kept but reinforced, with teeth strong enough for light M.D. Capture bite: 1D6 M.D., then the dog keeps its grip and pulls, so the victim cannot use the held limb, shoots wild at -4 to strike, is -4 to dodge, moves at half speed or less and is -30% on skills. It lets go only when its handler says so, when hurt enough, or when someone stronger pries the jaws apart, which only turns it on the hands or throat; attacked, it goes for the gun or the hand that grips it, and takes a kill shot at the neck or groin if one opens.'),
  ('sovietski-cyborg-canine', 2, 'Back-Mounted Ion or Laser Blaster (1)', 'Light ion blaster: 3D6 M.D. per single blast. Laser: 2D6 M.D.', 1, 'Ion blaster: 500 feet (152 m). Laser: 1,000 feet (305 m).', 'Fired remotely, each blast is one of the handler''s own melee attacks; reliable remote range 5 miles (8 km) in forest or city, 10 miles (16 km) on open steppe, 2 miles (3.2 km) in mountains or underground. Under its Gromeko Friend and Foe Identification computer it fires up to three times per melee round, and only at a target confirmed at 97% or better. Either way these shots are in addition to the dog''s own attacks.', 'Effectively unlimited; tied to the cyborg''s nuclear power supply.', NULL, 'Defense. Many, not all, canine Light Machines carry one. It rises from a low profile on the back to fire over the head or beside the dog, turns 360 degrees with a 30 degree arc up and down, and has a camera under the barrel (2,000 foot/610 m range, 2x and 8x zoom) so the handler sees where it points as well as what the dog sees.'),
  ('sovietski-cyborg-bear', 1, 'Bionic Jaws', '2D6 M.D. per full strength bite; 1D4x10 S.D.C./Hit Points on a restrained warning bite', 1, 'Melee.', NULL, NULL, NULL, 'Hunting, attack and defense. The head is kept but reinforced, with teeth strong enough for light M.D.'),
  ('sovietski-cyborg-bear', 2, 'Vibro-Claws', '3D6+3 M.D. per claw strike; 6D6+5 M.D. power claw strike (two attacks, only when reared up)', 1, 'Melee.', NULL, NULL, NULL, 'Close combat. The long claws are Vibro-Blades for slashing, clawing or digging.'),
  ('sovietski-cyborg-bear', 3, 'Back-Mounted Ion or Laser Blaster (1)', 'Heavy ion blaster: 5D6 M.D. per single blast. Double-barreled laser: 4D6 M.D. per dual blast.', 1, 'Ion blaster: 1,200 feet (366 m). Laser: 2,000 feet (610 m).', 'Fired remotely, each single or dual blast is one of the handler''s own melee attacks; reliable remote range 5 miles (8 km) in forest or city, 10 miles (16 km) on open steppe, 2 miles (3.2 km) in mountains or underground. Under its Gromeko Friend and Foe Identification computer it fires up to three times per melee round. Otherwise it works as the canine''s does.', 'Effectively unlimited; tied to the cyborg''s nuclear power supply.', NULL, 'Defense. Every full conversion combat bear carries one. It rises from a low profile on the back to fire forward, aside or behind, turns 360 degrees with a 30 degree arc up and down, and has a camera under the barrel (2,000 foot/610 m range, 2x, 5x and 8x zoom) so the handler sees where it points as well as what the bear sees.'),
  ('sovietski-cyborg-bear', 4, 'Mini-Missile Launchers (4; legs)', 'Varies with missile type; typically fragmentation, 5D6 M.D. to everything in a 20 foot (6.1 m) radius', 1, 'One mile (1.6 km).', 'One at a time or in volleys of 2 or 4.', '12 missiles in all, three per leg.', NULL, 'Assault and defense; extra firepower against infantry. A pop-out launcher hidden in each front shoulder and each hindquarter, behind a sliding panel that closes flush after firing; each turns 360 degrees to fire forward, up, down or back.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 2 machines are in' AS assertion, count(*) AS got, 2 AS want
  FROM vehicles WHERE slug IN ('sovietski-cyborg-canine', 'sovietski-cyborg-bear');
SELECT 'their 10 locations are in' AS assertion, count(*) AS got, 10 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('sovietski-cyborg-canine', 'sovietski-cyborg-bear');
SELECT 'their 6 weapon entries are in' AS assertion, count(*) AS got, 6 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('sovietski-cyborg-canine', 'sovietski-cyborg-bear');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('sovietski-cyborg-canine', 'sovietski-cyborg-bear') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

